// Traducciones al inglés de las funciones agregadas en la versión 1.1 (misma regla que `traduccionesIngles`).
let traduccionesExtras: [String: String] = [
    "Donde trabajás": "Where you work",
    "Listo, ya está todo copiado. Así se usa:": "Done, everything is copied. Here's how to use it:",
